  'Comprende la instalación de ayudas a la navegación por medio de la señalización marítima y fluvial (Boyas, faros, balizas, enfilaciones, racons y otros - AIS- Sistema de Identificación Automática) para brindar información oportuna sobre: los peligros en las proximidades a la costa, y señalizar los canales navegables de puertos públicos. De igual forma, lo anterior permite una navegación expedita y segura a las embarcaciones  en la jurisdicción marítima colombiana, de acuerdo a los estándares internacionales.',
